def transform_new(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    counts={}
    for row in g:
        for v in row:
            if v not in (2,8): counts[v]=counts.get(v,0)+1
    bg=max(counts,key=counts.get)
    # Find the straight divider of color 2.
    if any(all(v==2 for v in row) for row in g):
        axis='r'; div=next(r for r,row in enumerate(g) if all(v==2 for v in row))
    else:
        axis='c'; div=next(c for c in range(w) if all(g[r][c]==2 for r in range(h)))
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg,2,8)]
    if not cells: return g
    coords=[r if axis=='r' else c for r,c,_ in cells]
    lo,hi=min(coords),max(coords)
    if hi<div:
        shift=div-1-hi
        marker=lo+shift-1
    else:
        shift=div+1-lo
        marker=hi+shift+1
    for r,c,_ in cells: g[r][c]=bg
    for r,c,v in cells:
        if axis=='r': g[r+shift][c]=v
        else: g[r][c+shift]=v
    if axis=='r' and 0<=marker<h:
        g[marker]=[8]*w
    elif axis=='c' and 0<=marker<w:
        for r in range(h): g[r][marker]=8
    return g

